/* Lot 109: relative lab(), lch(), hwb() and color(), unclamped out-of-gamut origins (generated by scripts/lot109_gen.py; expectations from scripts/lot109_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_cssprop.h"

static char g_o[64];

/* 1, the 24-bit colour and the alpha (0..255) the reader paints, or 0 */
static const char *col(const char *v) {
    unsigned int rgb = 0;
    int a = 0;
    if (!wf_cssprop_color(v, (int)strlen(v), &rgb, &a)) return "0";
    snprintf(g_o, sizeof(g_o), "1 %06x %d", rgb, a);
    return g_o;
}

static void test_l109_rel_0(void) {
    TEST_ASSERT_EQUAL_STRING("1 d77961 255", col("lch(from rgb(245 99 66 / -0.5) l calc(c * 0.5 + 10) 40 / 1)"));
    TEST_ASSERT_EQUAL_STRING("1 0d5700 64", col("rgba(from oklab(from rgb(21 116 90 / 50%) calc(l + 0.2) a 0.5 / calc(alpha / 2)) 12.5 calc(g - 45) alpha)"));
    TEST_ASSERT_EQUAL_STRING("1 ffffff 255", col("oklab(from hwb(120 10% 20%) calc(l + 0.5) calc(b) b)"));
    TEST_ASSERT_EQUAL_STRING("0", col("oklch(from hwb(from hsla(77deg 100% 17% / 150%) b 30 calc(b * 2)), calc(l * 0.5 + 0.5) calc(c * 0.5 + 0.2) h)"));
    TEST_ASSERT_EQUAL_STRING("0", col("oklch(from oklch(0.6 0.1 200) calc(l + 0.5) calc(c + 10%) 0.1)"));
    TEST_ASSERT_EQUAL_STRING("1 6d6d6d 128", col("lch(from hwb(10rad 71% 74 /0.5) calc(l * 0.5 + 20) c 50)"));
    TEST_ASSERT_EQUAL_STRING("0", col("rgb(from rebeccapurple calc(alpha) g calc(alpha + 100) / 1 / 1)"));
    TEST_ASSERT_EQUAL_STRING("1 00b6c2 255", col("color(from lab(50 20 -30) srgb -0.1 calc(g * 0.5 + 0.5) calc(r * 0.5 + 0.5))"));
    TEST_ASSERT_EQUAL_STRING("0", col("HWB(from hwb(120 10% 20%) h calc(w + 10%) 60 / none)"));
    TEST_ASSERT_EQUAL_STRING("0", col("hsl(from color(xyz 0.5 0.9 0.1) h h calc(l + 10%))"));
    TEST_ASSERT_EQUAL_STRING("0", col("oklab(from lch(from oklab(0.6 -0.3 0.1) 40 l calc(h + 10%)) l a b)"));
    TEST_ASSERT_EQUAL_STRING("0", col("color(from lab(50 -100 50) display-p3, calc(r + 0.5) 1.2 none)"));
    TEST_ASSERT_EQUAL_STRING("0", col("hwb(from indianred calc(h / 2) calc(w + 10%) calc(b * 0.5 + 10))"));
    TEST_ASSERT_EQUAL_STRING("1 c2bb00 255", col("color(from color(srgb-linear 1.2 0.5 -0.1) prophoto-rgb calc(r * 0.5 + 0.2) calc(g - 0.05) b)"));
    TEST_ASSERT_EQUAL_STRING("1 fff4f1 255", col("hsl(from lab(100 100 100) h calc(s * 2) l)"));
    TEST_ASSERT_EQUAL_STRING("0", col("color(from olive lab calc(r + 0.2) calc(g / 2) calc(g + 0.05) / 1)"));
    TEST_ASSERT_EQUAL_STRING("0", col("hwb(from oklab(0.6 -0.3 0.1), calc(h * 0.5 + 100) calc(w - 20) calc(b * 2))"));
    TEST_ASSERT_EQUAL_STRING("1 5c78aa 255", col("lab(from color(srgb-linear 0.1 0.2 0.3) l 0 -30 / 1)"));
    TEST_ASSERT_EQUAL_STRING("1 b6005c 0", col("color(from hwb(180 35% 100%) xyz calc(y + 0.5) y z / none)"));
    TEST_ASSERT_EQUAL_STRING("1 ff436c 255", col("oklch(from color(xyz 0.2 0.2 0.2) calc(l + 0.1) alpha calc(h / 2))"));
}

